// Generate morning brief content
const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const brief = {
  date: today,
  company: 'IntegrateWise',
  sections: [
    {
      title: '🎯 Today's Focus',
      items: [
        'Review overnight AI processing results',
        'Check connector health status',
        'Review pending approvals queue'
      ]
    },
    {
      title: '📊 System Status',
      items: [
        'MCP Connector: Online',
        'Knowledge Service: Online',
        'Think Service: Online',
        'Gateway: Online'
      ]
    },
    {
      title: '🔔 Notifications',
      items: [
        'Dogfooding deployment complete',
        'All core services operational'
      ]
    }
  ]
};

return [{json: brief}];

parameters.text:
={{
const sections = $json.sections;
let email = `🌅 Good Morning!\n\n`;
email += `📅 ${$json.date}\n\n`;
email += `═══════════════════════════\n\n`;

sections.forEach(section => {
  email += `${section.title}\n`;
  email += `${section.title.replace(/./g, '=')}\n\n`;
  section.items.forEach(item => {
    email += `  • ${item}\n`;
  });
  email += `\n`;
});

email += `═══════════════════════════\n`;
email += `Generated by IntegrateWise AI\n`;
email += `https://app.integratewise.ai`;

return email;
        }
